jQuery(document).ready(function($) {
    function karaviAiAssistantUi(key, fallback) {
        return (window.karaviAiAssistantAdmin && karaviAiAssistantAdmin.uiStrings && karaviAiAssistantAdmin.uiStrings[key]) ? karaviAiAssistantAdmin.uiStrings[key] : fallback;
    }
    window.karaviAiAssistantUi = karaviAiAssistantUi;
    // --- Model Fetching Logic ---
    function syncProviderUI(providerSelectElement) {
        var $providerSelect = $(providerSelectElement);
        var variation = $providerSelect.data('variation');
        var selectedProvider = $providerSelect.val();
        var $variationWrapper = $providerSelect.closest('.inside');
        var $apiKeyWrapper = $variationWrapper.find('.api-key-wrapper[data-variation="' + variation + '"]');
        $apiKeyWrapper.find('.api-key-input').hide();
        var $providerInputWrapper = $apiKeyWrapper.find('.api-key-input[data-provider="' + selectedProvider + '"]');
        $providerInputWrapper.show();
        var $apiKeyInput = $providerInputWrapper.find('.karavi-ai-assistant-api-key-input');
        if ($apiKeyInput.val()) {
            fetchModelsForProvider(variation, selectedProvider, $apiKeyInput.val());
        } else {
            handleModelFetchError($('.karavi-ai-assistant-model-select[data-variation="' + variation + '"]'), karaviAiAssistantUi('enterApiKeyFetchModels', 'Enter API key to fetch models.'));
        }
    }

    function getOpenAiApiBaseUrl(variation) {
        var $input = $('.karavi-ai-assistant-openai-api-base-url-input[data-variation="' + variation + '"]');
        return $input.length ? String($input.val() || '').trim() : '';
    }

    function appendOpenAiBaseUrlPayload(payload, provider, variation) {
        if (provider === 'openai') {
            payload.openai_api_base_url = getOpenAiApiBaseUrl(variation);
        }
        return payload;
    }

    function isModelCombobox($modelField) {
        return $modelField.is('input.karavi-ai-assistant-model-combobox');
    }

    function getModelDatalist($modelField) {
        var listId = $modelField.attr('list');
        return listId ? $('#' + listId) : $();
    }

    function populateModelDatalist($modelField, models) {
        var $datalist = getModelDatalist($modelField);
        if (!$datalist.length) {
            return;
        }
        $datalist.empty();
        models.forEach(function(model) {
            var $option = $('<option>', {
                value: model.id
            });
            if (model.name && model.name !== model.id) {
                $option.attr('label', model.name);
            }
            $datalist.append($option);
        });
    }

    function ensureSavedModelInDatalist($modelField, savedModel) {
        if (!savedModel) {
            return;
        }
        var $datalist = getModelDatalist($modelField);
        if (!$datalist.length) {
            return;
        }
        var exists = false;
        $datalist.find('option').each(function() {
            if ($(this).attr('value') === savedModel) {
                exists = true;
            }
        });
        if (!exists) {
            $datalist.append($('<option>', {
                value: savedModel
            }));
        }
    }

    function fetchModelsForProvider(variation, provider, apiKey) {
        var $modelField = $('.karavi-ai-assistant-model-select[data-variation="' + variation + '"]');
        var $spinner = $modelField.siblings('.karavi-ai-assistant-model-spinner').first();
        var savedModel = $modelField.data('saved-model') || '';
        var combobox = isModelCombobox($modelField);
        $spinner.addClass('is-active');
        if (combobox) {
            $modelField.prop('readonly', true).attr('placeholder', karaviAiAssistantUi('fetchingModels', 'Fetching models...'));
        } else {
            $modelField.prop('disabled', true).empty().append('<option>' + karaviAiAssistantUi('fetchingModels', 'Fetching models...') + '</option>');
        }
        $.ajax({
            url: karaviAiAssistantAdmin.restUrl + 'fetch-models',
            method: 'POST',
            contentType: 'application/json',
            beforeSend: function(xhr) {
                xhr.setRequestHeader('X-WP-Nonce', karaviAiAssistantAdmin.nonce)
            },
            data: JSON.stringify(appendOpenAiBaseUrlPayload({
                provider: provider,
                api_key: apiKey
            }, provider, variation))
        }).done(function(response) {
            if (response.success && response.models.length) {
                if (combobox) {
                    populateModelDatalist($modelField, response.models);
                    ensureSavedModelInDatalist($modelField, savedModel);
                    if (savedModel) {
                        $modelField.val(savedModel);
                    } else {
                        var recommendedModel = '';
                        response.models.forEach(function(model) {
                            if (!recommendedModel && model.name && model.name.toLowerCase().indexOf('recommended') !== -1) {
                                recommendedModel = model.id;
                            }
                        });
                        if (recommendedModel) {
                            $modelField.val(recommendedModel);
                        }
                    }
                } else {
                    $modelField.empty();
                    var isSavedModelPresent = false;
                    response.models.forEach(function(model) {
                        var isRecommended = model.name.toLowerCase().includes('recommended');
                        var optionText = model.name;
                        var $option = $('<option>', {
                            value: model.id,
                            text: optionText
                        });
                        if (model.id === savedModel) {
                            $option.prop('selected', true);
                            isSavedModelPresent = true
                        }
                        $modelField.append($option)
                    });
                    if (!isSavedModelPresent && savedModel) {
                        $modelField.append($('<option>', {
                            value: savedModel,
                            text: savedModel,
                            selected: true
                        }))
                    }
                    if (!isSavedModelPresent && response.models.some(m => m.name.toLowerCase().includes('recommended'))) {
                        $modelField.val($modelField.find('option:contains(Recommended)').val())
                    }
                }
            } else {
                handleModelFetchError($modelField, karaviAiAssistantUi('noCompatibleModels', 'No compatible models found.'))
            }
        }).fail(function(jqXHR) {
            var message = jqXHR.responseJSON && jqXHR.responseJSON.message ? jqXHR.responseJSON.message : karaviAiAssistantUi('couldNotFetchModels', 'Could not fetch models.');
            handleModelFetchError($modelField, message)
        }).always(function() {
            $spinner.removeClass('is-active');
            if (combobox) {
                $modelField.prop('readonly', false).attr('placeholder', karaviAiAssistantUi('selectModelPlaceholder', 'Select from list or type model ID'));
            } else {
                $modelField.prop('disabled', false)
            }
        })
    }

    function handleModelFetchError($modelField, message) {
        var savedModel = $modelField.data('saved-model') || '';
        if (isModelCombobox($modelField)) {
            if (savedModel) {
                $modelField.val(savedModel);
                ensureSavedModelInDatalist($modelField, savedModel);
            }
            $modelField.attr('placeholder', savedModel ? message : (message + karaviAiAssistantUi('typeModelIdManuallySuffix', ' — type model ID manually')));
            return;
        }
        $modelField.empty();
        if (savedModel) {
            $modelField.append($('<option>', {
                value: savedModel,
                text: savedModel
            }))
        }
        $modelField.append($('<option>', {
            value: '',
            disabled: true,
            selected: !savedModel
        }).text(message))
    }

    function getRoutingApiKey(provider) {
        var $input = $('.api-key-wrapper[data-variation="a"] .api-key-input[data-provider="' + provider + '"] .karavi-ai-assistant-api-key-input');
        return $input.length ? $input.val() : ''
    }

    function fetchModelsForRouting(provider, apiKey) {
        var $modelSelect = $('.karavi-ai-assistant-routing-model-select');
        if (!$modelSelect.length) {
            return
        }
        var $spinner = $modelSelect.next('.karavi-ai-assistant-routing-model-spinner');
        $spinner.addClass('is-active');
        $modelSelect.prop('disabled', true).empty().append('<option>' + karaviAiAssistantUi('fetchingModels', 'Fetching models...') + '</option>');
        $.ajax({
            url: karaviAiAssistantAdmin.restUrl + 'fetch-models',
            method: 'POST',
            contentType: 'application/json',
            beforeSend: function(xhr) {
                xhr.setRequestHeader('X-WP-Nonce', karaviAiAssistantAdmin.nonce)
            },
            data: JSON.stringify(appendOpenAiBaseUrlPayload({
                provider: provider,
                api_key: apiKey
            }, provider, 'a'))
        }).done(function(response) {
            if (response.success && response.models.length) {
                $modelSelect.empty();
                var savedModel = $modelSelect.data('saved-model') || '';
                var isSavedModelPresent = false;
                response.models.forEach(function(model) {
                    var optionText = model.name;
                    var $option = $('<option>', {
                        value: model.id,
                        text: optionText
                    });
                    if (model.id === savedModel) {
                        $option.prop('selected', true);
                        isSavedModelPresent = true
                    }
                    $modelSelect.append($option)
                });
                if (!isSavedModelPresent && savedModel) {
                    $modelSelect.append($('<option>', {
                        value: savedModel,
                        text: savedModel,
                        selected: true
                    }))
                }
            } else {
                handleModelFetchError($modelSelect, karaviAiAssistantUi('noCompatibleModels', 'No compatible models found.'))
            }
        }).fail(function(jqXHR) {
            var message = jqXHR.responseJSON && jqXHR.responseJSON.message ? jqXHR.responseJSON.message : karaviAiAssistantUi('couldNotFetchModels', 'Could not fetch models.');
            handleModelFetchError($modelSelect, message)
        }).always(function() {
            $spinner.removeClass('is-active');
            $modelSelect.prop('disabled', false)
        })
    }

    function initRoutingModelFetch() {
        var $providerSelect = $('.karavi-ai-assistant-routing-provider-select');
        if (!$providerSelect.length) return;
        var provider = $providerSelect.val();
        if (!provider) {
            handleModelFetchError($('.karavi-ai-assistant-routing-model-select'), karaviAiAssistantUi('selectProviderFetchModels', 'Select a provider to fetch models.'));
            return
        }
        var apiKey = getRoutingApiKey(provider);
        if (!apiKey) {
            handleModelFetchError($('.karavi-ai-assistant-routing-model-select'), karaviAiAssistantUi('enterProviderApiKey', 'Enter API key for this provider to fetch models.'));
            return
        }
        fetchModelsForRouting(provider, apiKey)
    }

    function imageModeIsIndependent() {
        var $mode = $('#karaviaiassistant_image_generator_ai_mode');
        return !$mode.length || $mode.val() === 'independent'
    }

    function maybeFetchImageModels(context, suppressErrors) {
        if (!context || !imageModeIsIndependent()) {
            return
        }
        var $modelSelect = $('.karavi-ai-assistant-image-model-select[data-context="' + context + '"]');
        var $provider = $('.karavi-ai-assistant-image-provider-select[data-context="' + context + '"]');
        var $apiInput = $('.karavi-ai-assistant-image-api-key-input[data-context="' + context + '"]');
        if (!$modelSelect.length || !$provider.length || !$apiInput.length) {
            return
        }
        var provider = $provider.val();
        var apiKey = $apiInput.val();
        if (!provider || !apiKey) {
            if (!suppressErrors) {
                handleModelFetchError($modelSelect, karaviAiAssistantUi('enterApiKeyFetchModels', 'Enter API key to fetch models.'))
            }
            return
        }
        fetchImageModels(context, provider, apiKey)
    }

    function getOpenAiApiBaseUrlAny() {
        var variations = ['a', 'b'];
        for (var i = 0; i < variations.length; i++) {
            var value = getOpenAiApiBaseUrl(variations[i]);
            if (value) {
                return value;
            }
        }
        return '';
    }

    function fetchImageModels(context, provider, apiKey) {
        var $modelSelect = $('.karavi-ai-assistant-image-model-select[data-context="' + context + '"]');
        if (!$modelSelect.length) {
            return
        }
        var $spinner = $modelSelect.next('.karavi-ai-assistant-image-model-spinner');
        $spinner.addClass('is-active');
        $modelSelect.prop('disabled', true).empty().append('<option>' + karaviAiAssistantUi('fetchingModels', 'Fetching models...') + '</option>');
        var imagePayload = {
            provider: provider,
            api_key: apiKey,
            mode: 'image'
        };
        if (provider === 'openai') {
            var variation = (context === 'a' || context === 'b') ? context : '';
            imagePayload.openai_api_base_url = variation ? getOpenAiApiBaseUrl(variation) : getOpenAiApiBaseUrlAny();
        }
        $.ajax({
            url: karaviAiAssistantAdmin.restUrl + 'fetch-models',
            method: 'POST',
            contentType: 'application/json',
            beforeSend: function(xhr) {
                xhr.setRequestHeader('X-WP-Nonce', karaviAiAssistantAdmin.nonce)
            },
            data: JSON.stringify(imagePayload)
        }).done(function(response) {
            if (response.success && response.models.length) {
                $modelSelect.empty();
                var savedModel = $modelSelect.data('saved-model') || '';
                var isSavedModelPresent = false;
                response.models.forEach(function(model) {
                    var optionText = model.name;
                    var $option = $('<option>', {
                        value: model.id,
                        text: optionText
                    });
                    if (model.id === savedModel) {
                        $option.prop('selected', true);
                        isSavedModelPresent = true
                    }
                    $modelSelect.append($option)
                });
                if (!isSavedModelPresent && savedModel) {
                    $modelSelect.append($('<option>', {
                        value: savedModel,
                        text: savedModel,
                        selected: true
                    }))
                }
                if (!isSavedModelPresent && response.models.some(m => m.name.toLowerCase().includes('recommended'))) {
                    $modelSelect.val($modelSelect.find('option:contains(Recommended)').val())
                }
            } else {
                handleModelFetchError($modelSelect, karaviAiAssistantUi('noCompatibleModels', 'No compatible models found.'))
            }
        }).fail(function(jqXHR) {
            var message = jqXHR.responseJSON && jqXHR.responseJSON.message ? jqXHR.responseJSON.message : karaviAiAssistantUi('couldNotFetchModels', 'Could not fetch models.');
            handleModelFetchError($modelSelect, message)
        }).always(function() {
            $spinner.removeClass('is-active');
            $modelSelect.prop('disabled', false)
        })
    }

    function initImageModelAutoFetch() {
        var initializedContexts = [];
        $('.karavi-ai-assistant-image-model-select').each(function() {
            var context = $(this).data('context');
            if (context && initializedContexts.indexOf(context) === -1) {
                initializedContexts.push(context);
                maybeFetchImageModels(context, true)
            }
        });
        $('.postbox').on('change', '.karavi-ai-assistant-image-provider-select', function() {
            var context = $(this).data('context');
            maybeFetchImageModels(context)
        });
        $('.postbox').on('blur', '.karavi-ai-assistant-image-api-key-input', function() {
            var context = $(this).data('context');
            maybeFetchImageModels(context)
        })
    }

    $('.karavi-ai-assistant-provider-select').each(function() {
        syncProviderUI(this)
    });
    $('.postbox').on('change', '.karavi-ai-assistant-provider-select', function() {
        syncProviderUI(this)
    });
    initRoutingModelFetch();
    $('body').on('change', '.karavi-ai-assistant-routing-provider-select', function() {
        initRoutingModelFetch()
    });
    $('.postbox').on('blur', '.karavi-ai-assistant-api-key-input', function() {
        var $input = $(this);
        var apiKey = $input.val();
        var provider = $input.data('provider');
        var variation = $input.data('variation');
        if (apiKey) {
            fetchModelsForProvider(variation, provider, apiKey);
            var $routingProvider = $('.karavi-ai-assistant-routing-provider-select');
            if ($routingProvider.length && variation === 'a' && $routingProvider.val() === provider) {
                fetchModelsForRouting(provider, apiKey)
            }
        }
    });
    $('.postbox').on('blur', '.karavi-ai-assistant-openai-api-base-url-input', function() {
        var variation = $(this).data('variation');
        var $apiKeyInput = $('.api-key-wrapper[data-variation="' + variation + '"] .api-key-input[data-provider="openai"] .karavi-ai-assistant-api-key-input');
        var apiKey = $apiKeyInput.val();
        if (apiKey) {
            fetchModelsForProvider(variation, 'openai', apiKey);
        }
    });
    initImageModelAutoFetch();

    // --- General Settings UI ---
    $('#ab_testing_enabled_toggle').on('change', function() {
        var $variationB = $('#variation_b_wrap');
        if (this.checked) {
            $variationB.addClass('active').show();
            $('.settings-main-area').css({
                'grid-template-columns': '1fr 1fr'
            });
        } else {
            $variationB.removeClass('active').hide();
            $('.settings-main-area').css({
                'grid-template-columns': '1fr'
            });
        }
    }).trigger('change');

    $('#karaviaiassistant_trigger_type').on('change', function() {
        var selectedType = $(this).val();
        $('#trigger_type_options .trigger-option').hide();
        $('#' + selectedType + '_options').show()
    }).trigger('change');

    // --- Unified Repeater Logic (No AJAX) ---
    function setItemState($item, state) {
        $item.attr('data-state', state);
    }

    function reindexItems($container, nameAttribute) {
        $container.children().each(function(index) {
            var $item = $(this);
            $item.find('[name]').each(function() {
                var currentName = $(this).attr('name');
                var newName = currentName.replace(new RegExp('\\[' + nameAttribute + '\\]\\[.*?\\]'), '[' + nameAttribute + '][' + index + ']');
                $(this).attr('name', newName);
            });
        });
    }

    // Initialize state for all repeater-like items
    $('.karavi-ai-assistant-repeater-item, .karavi-ai-assistant-goal-item').each(function() {
        var initialState = $(this).attr('data-state');
        setItemState($(this), initialState);
    });

    // Add new Quick Chat button
    $('body').on('click', '.karavi-ai-assistant-add-repeater-item', function() {
        var $container = $(this).closest('.karavi-ai-assistant-repeater-container');
        var $repeaterItems = $container.find('.karavi-ai-assistant-repeater-items');
        var variation = $repeaterItems.data('variation');
        var index = $repeaterItems.children().length;

        var template = $container.find('.karavi-ai-assistant-repeater-template').html()
            .replace(/__INDEX__/g, index)
            .replace(/variation_.__/g, 'variation_' + variation);

        var $newItem = $(template);
        $repeaterItems.append($newItem);
        setItemState($newItem, 'edit');
    });

    // Add new Conversion Goal
    $('#karavi-ai-assistant-add-goal').on('click', function() {
        var $container = $('#karavi-ai-assistant-goals-container');
        var index = $container.children().length;
        var template = $('#karavi-ai-assistant-goal-template').html().replace(/__INDEX__/g, index);
        var $newItem = $(template);
        $container.append($newItem);
        setItemState($newItem, 'edit');
    });

    // Quick Chat repeater only — goals/triggers use dedicated handlers in inline admin JS
    $('body').on('click', '.karavi-ai-assistant-repeater-item .karavi-ai-assistant-done-item', function() {
        var $item = $(this).closest('.karavi-ai-assistant-repeater-item');
        var $labelField = $item.find('.karavi-ai-assistant-action-label');
        var label = $labelField.val();

        if (!label || label.trim() === '') {
            alert(karaviAiAssistantUi('labelOrNameRequired', 'Label or Name is required.'));
            $labelField.focus();
            return;
        }

        $item.find('.karavi-ai-assistant-item-label').text(label);
        setItemState($item, 'view');
    });

    // Quick Chat repeater only — goals/triggers use dedicated handlers in inline admin JS
    $('body').on('click', '.karavi-ai-assistant-repeater-item .karavi-ai-assistant-edit-item', function() {
        var $item = $(this).closest('.karavi-ai-assistant-repeater-item');
        setItemState($item, 'edit');
    });

    $('body').on('click', '.karavi-ai-assistant-repeater-item .karavi-ai-assistant-remove-item', function() {
        if (!confirm(karaviAiAssistantUi('removeItemConfirm', 'Are you sure you want to remove this item? This cannot be undone until you save changes.'))) return;

        var $item = $(this).closest('.karavi-ai-assistant-repeater-item');
        var $container = $item.parent();

        $item.fadeOut(300, function() {
            $(this).remove();
            reindexItems($container, 'actions');
        });
    });

    // Handle type change for Quick Chat buttons
    $('body').on('change', '.karavi-ai-assistant-action-type', function() {
        var type = $(this).val();
        var $editor = $(this).closest('.karavi-ai-assistant-item-editor');
        $editor.find('.karavi-ai-assistant-action-target').toggle(type === 'url');
        $editor.find('.karavi-ai-assistant-action-message').toggle(type === 'message');
        $editor.find('.karavi-ai-assistant-action-context').toggle(type === 'message');
    });

    // --- Media Uploader ---
    $('body').on('click', '.karavi-ai-assistant-media-uploader .upload-button', function(e) {
        e.preventDefault();
        var $uploader = $(this).closest('.karavi-ai-assistant-media-uploader');
        var frame = wp.media({
            title: karaviAiAssistantUi('selectLogo', 'Select Logo'),
            button: {
                text: karaviAiAssistantUi('useThisLogo', 'Use this logo')
            },
            multiple: false
        });
        frame.on('select', function() {
            var attachment = frame.state().get('selection').first().toJSON();
            $uploader.find('.media-url').val(attachment.url);
            $uploader.find('.image-preview-wrapper').html('<img src="' + attachment.url + '" style="max-width:64px;max-height:64px;border-radius:50%;">');
            $uploader.find('.remove-button').show()
        });
        frame.open()
    });
    $('body').on('click', '.karavi-ai-assistant-media-uploader .remove-button', function(e) {
        e.preventDefault();
        var $uploader = $(this).closest('.karavi-ai-assistant-media-uploader');
        $uploader.find('.media-url').val('');
        $uploader.find('.image-preview-wrapper').html('');
        $(this).hide()
    });

    // --- Content Engine AJAX ---
    function showGenerationStatus($statusDiv, response) {
        $statusDiv.removeClass('notice-success notice-error').hide();
        if (response) {
            $statusDiv.addClass(response.success ? 'notice-success' : 'notice-error');
            var content = response.analysis ? response.analysis.replace(/\n/g, '<br>') : response.message || '';
            $statusDiv.html(content);
            $statusDiv.show()
        }
    }

    function generatePostNow() {
        return $.ajax({
            url: karaviAiAssistantAdmin.restUrl + 'generate-post-now',
            method: 'POST',
            beforeSend: function(xhr) {
                xhr.setRequestHeader('X-WP-Nonce', karaviAiAssistantAdmin.nonce)
            }
        })
    }
    $('#karaviaiassistant_generate_keywords_button').on('click', function() {
        var $button = $(this);
        var description = $('#karaviaiassistant_keyword_business_description').val();
        if (description.trim()) {
            $button.prop('disabled', true).next('.spinner').addClass('is-active');
            $.ajax({
                url: karaviAiAssistantAdmin.restUrl + 'generate-keywords',
                method: 'POST',
                beforeSend: function(xhr) {
                    xhr.setRequestHeader('X-WP-Nonce', karaviAiAssistantAdmin.nonce)
                },
                data: {
                    description: description
                },
                success: function(response) {
                    var $keywordsTextarea = $('#karaviaiassistant_post_generator_keywords');
                    var currentKeywords = $keywordsTextarea.val().trim();
                    var newKeywords = response.keywords.trim();
                    $keywordsTextarea.val(currentKeywords ? currentKeywords + '\n' + newKeywords : newKeywords)
                },
                error: function(jqXHR) {
                    var message = jqXHR.responseJSON && jqXHR.responseJSON.message ? jqXHR.responseJSON.message : karaviAiAssistantUi('unknownErrorOccurred', 'An unknown error occurred.');
                    alert(karaviAiAssistantUi('errorGeneratingKeywords', 'Error generating keywords: ') + message)
                },
                complete: function() {
                    $button.prop('disabled', false).next('.spinner').removeClass('is-active')
                }
            })
        } else {
            alert(karaviAiAssistantUi('businessDescriptionFirst', 'Please provide a business description first.'))
        }
    });
    $('#karaviaiassistant_generate_post_now_button, #karaviaiassistant_generate_post_now_button_dashboard').on('click', function() {
        var buttonId = $(this).attr('id');
        var $button = $('#' + buttonId);
        var $statusDiv = buttonId === 'karaviaiassistant_generate_post_now_button' ? $('#karavi-ai-assistant-post-generation-status') : $('#karavi-ai-assistant-dashboard-generation-status');
        $button.prop('disabled', true).next('.spinner').addClass('is-active');
        $statusDiv.hide();
        generatePostNow().done(function(response) {
            showGenerationStatus($statusDiv, {
                success: true,
                message: response.message
            })
        }).fail(function(jqXHR) {
            var message = jqXHR.responseJSON && jqXHR.responseJSON.message ? jqXHR.responseJSON.message : karaviAiAssistantUi('unknownErrorOccurred', 'An unknown error occurred.');
            showGenerationStatus($statusDiv, {
                success: false,
                message: '<strong>' + karaviAiAssistantUi('errorPrefix', 'Error:') + '</strong> ' + message
            })
        }).always(function() {
            $button.prop('disabled', false).next('.spinner').removeClass('is-active')
        })
    });
    $('#karaviaiassistant_analyze_topic_button').on('click', function() {
        var $button = $(this);
        var $statusDiv = $('#karavi-ai-assistant-topic-analysis-results');
        var topic = $('#karaviaiassistant_topic_analysis_input').val();
        if (!topic.trim()) {
            alert(karaviAiAssistantUi('enterTopicToAnalyze', 'Please enter a topic to analyze.'));
            return
        }
        $button.prop('disabled', true).next('.spinner').addClass('is-active');
        $statusDiv.hide();
        $.ajax({
            url: karaviAiAssistantAdmin.restUrl + 'analyze-topic',
            method: 'POST',
            beforeSend: function(xhr) {
                xhr.setRequestHeader('X-WP-Nonce', karaviAiAssistantAdmin.nonce)
            },
            data: {
                topic: topic
            }
        }).done(function(response) {
            showGenerationStatus($statusDiv, {
                success: true,
                analysis: response.analysis
            })
        }).fail(function(jqXHR) {
            var message = jqXHR.responseJSON && jqXHR.responseJSON.message ? jqXHR.responseJSON.message : karaviAiAssistantUi('unknownErrorOccurred', 'An unknown error occurred.');
            showGenerationStatus($statusDiv, {
                success: false,
                message: '<strong>' + karaviAiAssistantUi('errorPrefix', 'Error:') + '</strong> ' + message
            })
        }).always(function() {
            $button.prop('disabled', false).next('.spinner').removeClass('is-active')
        })
    });
    var seoSuggestionStore = karaviAiAssistantAdmin && Array.isArray(karaviAiAssistantAdmin.seoSuggestions) ? karaviAiAssistantAdmin.seoSuggestions.slice() : [];
    function escapeHtml(str) {
        return String(str || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;')
    }
    function formatSuggestionAnalysis(text) {
        return escapeHtml(text).replace(/\n/g, '<br>')
    }
    function renderSeoSuggestionList() {
        var $list = $('#karavi-ai-assistant-seo-suggestion-list');
        if (!$list.length) return;
        if (!seoSuggestionStore.length) {
            $list.html('<div class="karavi-ai-assistant-seo-suggestion-empty">' + escapeHtml(karaviAiAssistantUi('seoSuggestionsEmpty', 'Saved SEO suggestions will appear here.')) + '</div>');
            return
        }
        var html = seoSuggestionStore.map(function(item) {
            var isPost = item && item.target_type === 'post' && Number(item.post_id || 0) > 0;
            var improved = !!(item && item.is_improved);
            var badges = '<span class="karavi-ai-assistant-seo-badge">' + escapeHtml(item.label || (isPost ? karaviAiAssistantUi('contentLabel', 'Content') : karaviAiAssistantUi('bulkScope', 'Bulk Scope'))) + '</span>';
            badges += item && item.is_generated ? '<span class="karavi-ai-assistant-seo-badge">' + escapeHtml(karaviAiAssistantUi('seoBadgeAi', 'AI')) + '</span>' : '<span class="karavi-ai-assistant-seo-badge">' + escapeHtml(karaviAiAssistantUi('seoBadgeManual', 'Manual')) + '</span>';
            if (improved) {
                badges += '<span class="karavi-ai-assistant-seo-badge karavi-ai-assistant-seo-badge-success">' + escapeHtml(karaviAiAssistantUi('seoBadgeImproved', 'Improved')) + '</span>'
            }
            var actions = '';
            if (isPost) {
                actions += '<button type="button" class="button button-small karavi-ai-assistant-toggle-improved" data-post-id="' + escapeHtml(item.post_id) + '" data-improved="' + (improved ? '1' : '0') + '">' + (improved ? karaviAiAssistantUi('removeImprovedTag', 'Remove Improved Tag') : karaviAiAssistantUi('markAsImproved', 'Mark as Improved')) + '</button>'
            }
            actions += '<button type="button" class="button button-small karavi-ai-assistant-delete-seo-suggestion" data-suggestion-id="' + escapeHtml(item.id || '') + '">' + escapeHtml(karaviAiAssistantUi('deleteLabel', 'Delete')) + '</button>';
            var meta = item && item.url ? '<a class="karavi-ai-assistant-seo-suggestion-link" href="' + escapeHtml(item.url) + '" target="_blank" rel="noopener noreferrer">' + escapeHtml(karaviAiAssistantUi('openContent', 'Open content')) + '</a>' : '';
            return '<article class="karavi-ai-assistant-seo-suggestion-card" data-suggestion-id="' + escapeHtml(item.id || '') + '">' + '<header class="karavi-ai-assistant-seo-suggestion-card-header"><div><h6>' + escapeHtml(item.title || karaviAiAssistantUi('seoSuggestionTitle', 'SEO Suggestion')) + '</h6><div class="karavi-ai-assistant-seo-suggestion-badges">' + badges + '</div></div><div class="karavi-ai-assistant-seo-suggestion-meta">' + meta + '</div></header>' + '<div class="karavi-ai-assistant-seo-suggestion-card-body">' + formatSuggestionAnalysis(item.analysis || '') + '</div>' + '<div class="karavi-ai-assistant-seo-suggestion-card-actions">' + actions + '</div>' + '</article>'
        }).join('');
        $list.html(html)
    }
    function updateSeoImprovementTargetFilters() {
        var term = String($('#karaviaiassistant_seo_improvement_search').val() || '').toLowerCase();
        var sourceFilter = String($('#karaviaiassistant_seo_improvement_source_filter').val() || 'any');
        var improvedFilter = String($('#karaviaiassistant_seo_improvement_improved_filter').val() || 'any');
        $('.karavi-ai-assistant-seo-improvement-target-option').each(function() {
            var $option = $(this);
            var label = String($option.data('label') || '');
            var isGenerated = String($option.attr('data-generated') || '0') === '1';
            var isImproved = String($option.attr('data-improved') || '0') === '1';
            var sourceMatches = sourceFilter === 'any' || (sourceFilter === 'ai_generated' && isGenerated) || (sourceFilter === 'manual' && !isGenerated);
            var improvedMatches = improvedFilter === 'any' || (improvedFilter === 'improved' && isImproved) || (improvedFilter === 'not_improved' && !isImproved);
            var termMatches = term === '' || label.indexOf(term) !== -1;
            $option.toggle(sourceMatches && improvedMatches && termMatches)
        })
    }
    function syncSeoTargetOption(postId, improved) {
        var normalizedPostId = String(postId || '');
        if (!normalizedPostId) return;
        $('.karavi-ai-assistant-seo-improvement-target-option').each(function() {
            var $option = $(this);
            var $checkbox = $option.find('.karavi-ai-assistant-seo-improvement-checkbox');
            if (String($checkbox.val() || '') !== normalizedPostId) {
                return
            }
            $option.attr('data-improved', improved ? '1' : '0');
            var $badges = $option.find('.karavi-ai-assistant-seo-improvement-target-badges');
            $badges.find('.karavi-ai-assistant-seo-badge-success').remove();
            if (improved) {
                $badges.append('<span class="karavi-ai-assistant-seo-badge karavi-ai-assistant-seo-badge-success">' + escapeHtml(karaviAiAssistantUi('seoBadgeImproved', 'Improved')) + '</span>')
            }
        });
        updateSeoImprovementTargetFilters()
    }
    renderSeoSuggestionList();
    $(document).on('input change', '#karaviaiassistant_seo_improvement_search, #karaviaiassistant_seo_improvement_source_filter, #karaviaiassistant_seo_improvement_improved_filter', updateSeoImprovementTargetFilters);
    updateSeoImprovementTargetFilters();
    $('#karaviaiassistant_suggest_seo_improvements_button').on('click', function() {
        var $button = $(this);
        var $statusDiv = $('#karavi-ai-assistant-seo-improvement-results');
        var checkedValues = $('.karavi-ai-assistant-seo-improvement-checkbox:checked').map(function() {
            return String($(this).val() || '')
        }).get();
        if (!checkedValues.length) {
            alert(karaviAiAssistantUi('chooseTargetsFirst', 'Please choose one or more targets first.'));
            return
        }
        var data = {
            post_ids: [],
            target_scopes: []
        };
        checkedValues.forEach(function(value) {
            if (0 === value.indexOf('scope:')) {
                data.target_scopes.push(value.replace('scope:', ''))
            } else {
                data.post_ids.push(value)
            }
        });
        $button.prop('disabled', true).next('.spinner').addClass('is-active');
        $statusDiv.hide();
        $.ajax({
            url: karaviAiAssistantAdmin.restUrl + 'suggest-seo-improvements',
            method: 'POST',
            beforeSend: function(xhr) {
                xhr.setRequestHeader('X-WP-Nonce', karaviAiAssistantAdmin.nonce)
            },
            data: data
        }).done(function(response) {
            seoSuggestionStore = response && Array.isArray(response.suggestions) ? response.suggestions.slice() : seoSuggestionStore;
            renderSeoSuggestionList();
            showGenerationStatus($statusDiv, {
                success: true,
                message: (Number(response.generated_count || 0) || data.post_ids.length || data.target_scopes.length) + ' SEO suggestion card(s) saved in the panel.'
            })
        }).fail(function(jqXHR) {
            var message = jqXHR.responseJSON && jqXHR.responseJSON.message ? jqXHR.responseJSON.message : karaviAiAssistantUi('unknownErrorOccurred', 'An unknown error occurred.');
            showGenerationStatus($statusDiv, {
                success: false,
                message: '<strong>' + karaviAiAssistantUi('errorPrefix', 'Error:') + '</strong> ' + message
            })
        }).always(function() {
            $button.prop('disabled', false).next('.spinner').removeClass('is-active')
        })
    });
    $('body').on('click', '.karavi-ai-assistant-delete-seo-suggestion', function() {
        var suggestionId = String($(this).data('suggestion-id') || '');
        if (!suggestionId) return;
        $.ajax({
            url: karaviAiAssistantAdmin.restUrl + 'delete-seo-suggestion',
            method: 'POST',
            beforeSend: function(xhr) {
                xhr.setRequestHeader('X-WP-Nonce', karaviAiAssistantAdmin.nonce)
            },
            data: {
                suggestion_id: suggestionId
            }
        }).done(function(response) {
            seoSuggestionStore = response && Array.isArray(response.suggestions) ? response.suggestions.slice() : [];
            renderSeoSuggestionList()
        }).fail(function(jqXHR) {
            alert(jqXHR.responseJSON && jqXHR.responseJSON.message ? jqXHR.responseJSON.message : karaviAiAssistantUi('couldNotDeleteSuggestion', 'Could not delete this suggestion.'))
        })
    });
    $('body').on('click', '.karavi-ai-assistant-toggle-improved', function() {
        var $button = $(this);
        var postId = Number($button.data('post-id') || 0);
        var improved = String($button.data('improved') || '0') !== '1';
        if (!postId) return;
        $button.prop('disabled', true);
        $.ajax({
            url: karaviAiAssistantAdmin.restUrl + 'set-seo-improved-status',
            method: 'POST',
            beforeSend: function(xhr) {
                xhr.setRequestHeader('X-WP-Nonce', karaviAiAssistantAdmin.nonce)
            },
            data: {
                post_id: postId,
                improved: improved ? '1' : '0'
            }
        }).done(function(response) {
            seoSuggestionStore = response && Array.isArray(response.suggestions) ? response.suggestions.slice() : seoSuggestionStore;
            renderSeoSuggestionList();
            syncSeoTargetOption(postId, !!response.improved)
        }).fail(function(jqXHR) {
            alert(jqXHR.responseJSON && jqXHR.responseJSON.message ? jqXHR.responseJSON.message : karaviAiAssistantUi('couldNotUpdateImproved', 'Could not update improved status.'))
        }).always(function() {
            $button.prop('disabled', false)
        })
    });

    // --- Tour Restart Logic ---
    $('#karavi-ai-assistant-restart-tour').on('click', function(e) {
        e.preventDefault();
        // Always start the tour from the dashboard using a prebuilt safe URL
        try {
            var url = (karaviAiAssistantAdmin && karaviAiAssistantAdmin.dashboard_url_start_tour) ? karaviAiAssistantAdmin.dashboard_url_start_tour : null;
            if (!url) {
                // Fallback: minimal risk of malformed URL but keeps UX working
                var base = (karaviAiAssistantAdmin && karaviAiAssistantAdmin.dashboard_url) ? karaviAiAssistantAdmin.dashboard_url : 'admin.php?page=karavi-ai-assistant-dashboard';
                url = base + (base.indexOf('?') !== -1 ? '&' : '?') + 'start_tour=true';
            }
            window.location.href = url;
        } catch (err) {
            window.location.href = 'admin.php?page=karavi-ai-assistant-dashboard&start_tour=true';
        }
    });
    // --- Permanent Dismiss Handler for Notices ---
    $('body').on('click', '.karavi-ai-assistant-dismiss-forever', function(e) {
        e.preventDefault();
        var $btn = $(this);
        var noticeId = $btn.data('notice');
        if (!noticeId) return;
        var $notice = $btn.closest('.notice');
        $btn.prop('disabled', true);
        $.post(karaviAiAssistantAdmin.ajax_url, {
            action: 'karaviaiassistant_dismiss_notice',
            notice_id: noticeId,
            nonce: karaviAiAssistantAdmin.dismissNonce
        }, function(response) {
            if (response && response.success) {
                $notice.slideUp(180, function() {
                    $(this).remove();
                });
            } else {
                alert(karaviAiAssistantUi('failedDismissNotice', 'Failed to dismiss notice.'));
                $btn.prop('disabled', false);
            }
        }).fail(function() {
            alert(karaviAiAssistantUi('failedDismissNotice', 'Failed to dismiss notice.'));
            $btn.prop('disabled', false);
        });
    });

    function togglePostGenProvider() {
        var $mode = $('#karaviaiassistant_post_generator_ai_mode');
        if (!$mode.length) return;
        var mode = $mode.val();
        var $rows = $('.karavi-ai-assistant-postgen-independent-row');
        var independent = mode === 'independent';
        independent ? $rows.show() : $rows.hide();
        $rows.find('.karavi-ai-assistant-postgen-required').each(function() {
            if (independent) {
                $(this).attr('required', 'required');
            } else {
                $(this).removeAttr('required');
            }
        });
    }
    togglePostGenProvider();
    $('body').on('change', '#karaviaiassistant_post_generator_ai_mode', togglePostGenProvider);

    function toggleImageProvider() {
        var $mode = $('#karaviaiassistant_image_generator_ai_mode');
        if (!$mode.length) return;
        var mode = $mode.val();
        var $rows = $('.karavi-ai-assistant-image-independent-row');
        var independent = mode === 'independent';
        independent ? $rows.show() : $rows.hide();
        if (independent) {
            maybeFetchImageModels('postgen_images', true);
        }
        $rows.find('.karavi-ai-assistant-image-required').each(function() {
            if (independent) {
                $(this).attr('required', 'required');
            } else {
                $(this).removeAttr('required');
            }
        });
    }
    toggleImageProvider();
    $('body').on('change', '#karaviaiassistant_image_generator_ai_mode', toggleImageProvider);

    function applyKaraviAdminThemeClass(theme) {
        var body = document.body;
        if (!body) return;
        body.classList.remove('karavi-ai-assistant-theme-auto', 'karavi-ai-assistant-theme-light', 'karavi-ai-assistant-theme-dark');
        body.classList.add('karavi-ai-assistant-theme-' + theme);
    }

    function cycleKaraviAdminTheme(current) {
        var cfg = (window.karaviAiAssistantAdmin && karaviAiAssistantAdmin.adminTheme) ? karaviAiAssistantAdmin.adminTheme : null;
        var order = (cfg && cfg.cycle && cfg.cycle.length) ? cfg.cycle : ['auto', 'light', 'dark'];
        var idx = order.indexOf(current);
        if (idx < 0) idx = 0;
        return order[(idx + 1) % order.length];
    }

    function updateKaraviAdminBarThemeLabel(theme) {
        var cfg = (window.karaviAiAssistantAdmin && karaviAiAssistantAdmin.adminTheme) ? karaviAiAssistantAdmin.adminTheme : null;
        var label = (cfg && cfg.labels && cfg.labels[theme]) ? cfg.labels[theme] : theme;
        $('#wp-admin-bar-karavi-ai-assistant-theme-toggle .karavi-ai-assistant-admin-bar-theme-label').text(label);
        if (cfg) cfg.current = theme;
    }

    $('body').on('click', '#wp-admin-bar-karavi-ai-assistant-theme-toggle a', function(e) {
        e.preventDefault();
        var cfg = (window.karaviAiAssistantAdmin && karaviAiAssistantAdmin.adminTheme) ? karaviAiAssistantAdmin.adminTheme : null;
        if (!cfg || !karaviAiAssistantAdmin.ajax_url) return;
        var nextTheme = cycleKaraviAdminTheme(cfg.current || 'auto');
        applyKaraviAdminThemeClass(nextTheme);
        updateKaraviAdminBarThemeLabel(nextTheme);
        $.post(karaviAiAssistantAdmin.ajax_url, {
            action: 'karaviaiassistant_set_admin_ui_theme',
            theme: nextTheme,
            nonce: cfg.nonce
        }).fail(function() {
            applyKaraviAdminThemeClass(cfg.current || 'auto');
            updateKaraviAdminBarThemeLabel(cfg.current || 'auto');
            alert(karaviAiAssistantUi('failedSaveAdminTheme', 'Could not save theme preference.'));
        });
    });
});
